mapper.select:
SELECT /* BoardMapper.checkBoardScrap (페이지 스크랩 여부  확인) */
       COUNT(*)
  FROM BOARD_SCRAP
 WHERE BOARD_ID = #{boardId}
   AND MEMBER_ID = #{memberId}

SELECT /* BoardMapper.getBoardListWithPaging (페이징 처리된 게시판 목록 조회 (지연 조인 최적화 적용)) */ B.BOARD_ID , B.TITLE , B.CONTENT , M.USER_ID , M.USER_NAME , B.MEMBER_ID , B.BOARD_CODE , B.CATEGORY_ID , B.VIEW_COUNT , B.LIKE_COUNT ,(SELECT COUNT(*) FROM COMMENT_MANAGEMENT CM WHERE CM.BOARD_ID = B.BOARD_ID AND CM.DELETE_YN = 'N') AS commentCount /* 댓글 작성 수 */ , M.PROFILE_IMAGE , B.CREATE_AT , B.UPDATE_AT , B.TAG_NAME FROM BOARD B INNER JOIN ( /* 인덱스만 사용하여 필요한 ID들만 빠르게 추출 */ SELECT BOARD_ID FROM BOARD
DELETE_YN = 'N'
AND BOARD_CODE = #{boardCode}
AND CATEGORY_ID = #{categoryId}
AND MEMBER_ID = #{memberId}
AND TAG_NAME LIKE CONCAT('%', #{tagName}, '%')
AND MATCH(TITLE, CONTENT) AGAINST(#{keyword} IN BOOLEAN MODE)
ORDER BY CREATE_AT DESC LIMIT #{size} OFFSET #{offset} ) AS temp ON B.BOARD_ID = temp.BOARD_ID LEFT JOIN MEMBER_INFO M ON B.MEMBER_ID = M.MEMBER_ID ORDER BY B.CREATE_AT DESC

SELECT /* BoardMapper.getgetBoardTotalCount (게시글 총 개수 조회) */
       COUNT(*)
  FROM BOARD

        DELETE_YN = 'N'

        AND BOARD_CODE = #{boardCode}


        AND CATEGORY_ID = #{categoryId}


        AND MEMBER_ID = #{memberId}


        AND MATCH(TITLE, CONTENT) AGAINST(#{keyword} IN BOOLEAN MODE)


        AND TAG_NAME LIKE CONCAT('%', #{tagName}, '%')

mapper.update:
UPDATE BOARD
   SET VIEW_COUNT = VIEW_COUNT + #{increaseCount}
 WHERE BOARD_ID = #{boardId}

UPDATE BOARD /* BoardMapper.updateBoardDeleteYn 게시글 삭제 시, 소프트 삭제 적용  */
   SET DELETE_YN = 'Y'
     , UPDATE_AT = NOW()
 WHERE MEMBER_ID = #{memberId}
   AND BOARD_ID In

     #{id}

UPDATE BOARD /* BoardMapper.updateBoard (게시글 수정)*/
   SET TITLE = #{title}
     , CONTENT = #{content}
     , BOARD_CODE = #{boardCode}
     , CATEGORY_ID = #{categoryId}
     , TAG_NAME = #{tagName}
     , UPDATE_AT = NOW()
WHERE BOARD_ID = #{boardId}

mapper.insert:
INSERT INTO BOARD ( /* BoardMapper.insertBoard (게시글 등록)*/
      TITLE
    , CONTENT
    , MEMBER_ID
    , USER_ID
    , BOARD_CODE
    , CATEGORY_ID
    , VIEW_COUNT
    , CREATE_AT
    , UPDATE_AT
    , TAG_NAME
) VALUES (
      #{title}
    , #{content}
    , #{memberId}
    , #{userId}
    , #{boardCode}
    , #{categoryId}
    , 0
    , NOW()
    , NOW()
    , #{tagName}
)

INSERT INTO BOARD_FILE ( /* BoardMapper.insertBoardFile (게시판 파일 등록) */
      BOARD_ID
    , ORIGIN_NAME
    , SAVE_NAME
    , FILE_PATH
    , FILE_SIZE
    , CREATE_AT
) VALUES (
      #{boardId}
    , #{originName}
    , #{saveName}
    , #{filePath}
    , #{fileSize}
    , NOW()
)

